-- Directory alphabetical sort (the /directory default): the page query is
-- `WHERE status = ? AND <freshness/filters> ORDER BY title COLLATE NOCASE ASC,
-- id DESC LIMIT ? OFFSET ?`, with the keyset cursor seeking on
-- `title COLLATE NOCASE >= ?`. No existing index matched that ORDER BY, so every
-- request did a full scan plus a temp B-tree sort. This composite index matches
-- the status equality + the exact sort keys (collation and direction included),
-- so SQLite walks it in order and stops after LIMIT rows. Generated by
-- drizzle-kit (declared in db/schema.ts); purely additive, touches no row.
CREATE INDEX `cameras_status_title_nocase_idx` ON `cameras` (`status`,title COLLATE NOCASE,id DESC);
